vrrp_script chk_app {
    script "/etc/keepalived/check_app.sh"   # 健康检查脚本
    interval 2          # 每 2 秒探测一次
    weight -30          # 失败时优先级减 30（100→70）
    fall 2              # 连续失败 2 次判定为故障
    rise 2              # 连续成功 2 次判定为恢复
}

vrrp_instance VI_1 {
    state BACKUP              # 初始角色声明：非抢占两端都必须写 BACKUP——
                              # nopreempt 只对初始 state=BACKUP 生效，
                              # 写 MASTER 则该选项无效；实际主备由 priority 决定
    interface eth0            # VRRP 通告与 VIP 所在接口
    virtual_router_id 51      # VRID：同一二层内唯一（1~255）
    priority 100              # 优先级：大者为主
    advert_int 1              # 通告间隔 1s
    nopreempt                 # 非抢占：故障恢复后不自动夺回主（防回切震荡）
    virtual_ipaddress {
        192.168.10.100/24     # VIP（可多个）
    }
    track_script {
        chk_app               # 挂载健康检查
    }
}

vrrp_instance VI_1 { interface eth0;  virtual_router_id 51; priority 100; ... }
vrrp_instance VI_2 { interface eth1;  virtual_router_id 52; priority 100; ... }
# 切换判据由监控层聚合两个 instance 的状态，避免单链路抖动误切

upstream app_pool {
    # 算法：默认轮询 round-robin；least_conn 最少连接；ip_hash 源地址保持
    least_conn;

    server 10.0.1.11:8080 weight=5 max_fails=3 fail_timeout=30s;
    server 10.0.1.12:8080 weight=5 max_fails=3 fail_timeout=30s;
    server 10.0.1.13:8080 backup;              # 备用节点：主全挂才启用

    keepalive 64;                               # 与后端的空闲长连接池
}

server {
    listen 80;
    location / {
        proxy_pass http://app_pool;
        proxy_http_version 1.1;
        proxy_set_header Connection "";          # 配合 keepalive 复用连接
        proxy_connect_timeout 3s;                # 连不上快速失败
        proxy_read_timeout 30s;
        proxy_next_upstream error timeout;       # 失败转下一台（重试）
        proxy_next_upstream_tries 2;             # 重试上限（防重试风暴）
    }
}

virtual_server 10.0.0.10 80 {
    delay_loop 6                 # 每 6 秒探测
    lb_algo rr
    lb_kind DR                   # DR 模式
    protocol TCP
    real_server 10.0.1.11 8080 {
        weight 1
        HTTP_GET {
            url { path /healthz  status_code 200 }
            connect_timeout 3
            retry 2              # 连败摘除
            delay_before_retry 2
        }
    }
    real_server 10.0.1.12 8080 { ...同上... }
}
